export function d01Strings(locale: string): Catalogue {
  return BY_LOCALE[locale] ?? BY_LOCALE.en;
}

/** `{name}` placeholders, filled without HTML. */
export function fillD01(template: string, values: Readonly<Record<string, string>>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => values[key] ?? match);
}
